# SolarPanel (t4-02) -- fully self-contained Blender script.
# Usage: Blender > Scripting workspace > Open this file > Run Script (Alt+P).
# Needs Blender 4.x/5.x (bundled numpy). No other files needed.
# To modify: edit ONLY section 3 (MODEL). Each shape line says what part it is and what its numbers mean.
# Sections 1-2 (engine, palette) are generated by ~/.claude/skills/blender-voxel-py/bundle.py.
#
# ---- spec.md (design intent) ----
#   ---
#   name: SolarPanel
#   id: t4-02
#   tier: T4
#   room: Roof
#   priority: V1
#   size_cm: 100x4x165
#   voxels: 128x5x211
#   grid: F
#   grain: 0
#   collider: false
#   states:
#     Clean: evenly blue cells, bright glass
#     Dirty: dust patches in a pale brown key, a few leaf voxels, duller glass
#     Damaged: diagonal crack lines across 3–4 cells, one missing cell corner, frame bent by 1–2 voxels
#   ---
#
#   # SolarPanel
#
#   ## Prompt
#
#   ### Shape
#   Build a voxel SolarPanel for the Roof room, about 100x4x165 cm (128x5x211 voxels). Main forms: frame, glass.
#
#   ### Materials
#   Use the colour keys in the Parts list, taken from `game-assets/palette.py`. Hard-edged blocks, grain 0.
#
#   ### Details
#   Add the small features: 60 cells, busbars, junction box, corner keys, label.
#
#   ## Parts (tier; cm size + colour key to fill before first build)
#
#   - [2] frame
#   - [2] glass
#   - [3] 60 cells (tile)
#   - [3] busbars
#   - [3] junction box
#   - [3] corner keys
#   - [3] label

# ======================================================================
# 1. VOXEL ENGINE (grid, shapes, greedy meshing, materials, export)
# ======================================================================
# Voxel model builder, numpy + bulk Mesh API edition. Exec inside Blender, then fill V and call build().
#   V = Grid()                  # dense uint16 array of material ids (0 = empty); +z up, -y = front
#   box(V, x0, x1, y0, y1, z0, z1, 'skin')   # inclusive ranges, negative coords allowed
#   hollow / tile / blob / disc / mirror_x / carve / rescale: same signatures as blender-voxel
#   result = build('Gnome', V, {'skin': (0.95, 0.62, 0.45), ...}, size=VOXEL_SIZE)
#   export_glb('Gnome', '//gnome.glb')
#
# Differences from blender-voxel (dict + bmesh):
#   - shapes are numpy slice assignments (no per-voxel Python loop)
#   - face culling and greedy merge are vectorised per slice
#   - mesh is written with Mesh.vertices.add / loops.add / polygons.add + foreach_set
#     (no bmesh, no per-face Python calls)
#   - build() returns 'ms' (timing breakdown) for benchmarking
import bpy, math, time
import numpy as np

VOXEL_SIZE = 1 / 64   # metres per voxel (64 per metre)
FINE_SIZE = 1 / 128   # hand-held props
MAX_FACES = 40000     # warn above this after meshing


# ---------------------------------------------------------------- grid

class Grid:
    """Dense, auto-growing voxel array. a[x - ox, y - oy, z - oz] = material id (0 = empty)."""

    def __init__(self):
        self.a = np.zeros((0, 0, 0), np.uint16)
        self.o = (0, 0, 0)
        self.keys = []          # id - 1 -> key
        self._id = {}

    def kid(self, key):
        i = self._id.get(key)
        if i is None:
            self.keys.append(key)
            i = self._id[key] = len(self.keys)
        return i

    def ensure(self, lo, hi):
        """Grow so that inclusive lattice range lo..hi fits."""
        if self.a.size == 0:
            self.o = tuple(lo)
            self.a = np.zeros(tuple(h - l + 1 for l, h in zip(lo, hi)), np.uint16)
            return
        cur_lo = self.o
        cur_hi = tuple(o + s - 1 for o, s in zip(self.o, self.a.shape))
        new_lo = tuple(min(a, b) for a, b in zip(lo, cur_lo))
        new_hi = tuple(max(a, b) for a, b in zip(hi, cur_hi))
        if new_lo == cur_lo and new_hi == cur_hi:
            return
        # grow with headroom so repeated small writes do not realloc every time
        pad = [4 if n != c else 0 for n, c in zip(new_lo, cur_lo)]
        pad_hi = [4 if n != c else 0 for n, c in zip(new_hi, cur_hi)]
        new_lo = tuple(n - p for n, p in zip(new_lo, pad))
        new_hi = tuple(n + p for n, p in zip(new_hi, pad_hi))
        b = np.zeros(tuple(h - l + 1 for l, h in zip(new_lo, new_hi)), np.uint16)
        s = tuple(slice(c - n, c - n + sz) for c, n, sz in zip(cur_lo, new_lo, self.a.shape))
        b[s] = self.a
        self.a, self.o = b, new_lo

    def view(self, x0, x1, y0, y1, z0, z1):
        self.ensure((x0, y0, z0), (x1, y1, z1))
        o = self.o
        return self.a[x0 - o[0]:x1 - o[0] + 1, y0 - o[1]:y1 - o[1] + 1, z0 - o[2]:z1 - o[2] + 1]

    def count(self):
        return int(np.count_nonzero(self.a))

    def bounds(self):
        nz = np.argwhere(self.a)
        lo, hi = nz.min(0), nz.max(0)
        return tuple(lo + self.o), tuple(hi + self.o)


# ---------------------------------------------------------------- shapes

def box(V, x0, x1, y0, y1, z0, z1, m):
    if x1 < x0 or y1 < y0 or z1 < z0:
        return
    V.view(x0, x1, y0, y1, z0, z1)[...] = V.kid(m)


def hollow(V, x0, x1, y0, y1, z0, z1, m, t=1):
    """Box shell, wall thickness t voxels (bezels, frames, trays, open crates)."""
    v = V.view(x0, x1, y0, y1, z0, z1)
    k = V.kid(m)
    ix = np.arange(x1 - x0 + 1)[:, None, None]
    iy = np.arange(y1 - y0 + 1)[None, :, None]
    iz = np.arange(z1 - z0 + 1)[None, None, :]
    d = np.minimum(np.minimum(np.minimum(ix, x1 - x0 - ix), np.minimum(iy, y1 - y0 - iy)),
                   np.minimum(iz, z1 - z0 - iz))
    v[d < t] = k


def tile(V, x0, x1, y0, y1, z0, z1, m, nx=1, ny=1, nz=1, dx=0, dy=0, dz=0):
    """Repeat a box nx*ny*nz times, stepping (dx, dy, dz) voxels: keys, vents, windows, tiles."""
    V.ensure((x0, y0, z0), (x1 + (nx - 1) * dx, y1 + (ny - 1) * dy, z1 + (nz - 1) * dz))
    for i in range(nx):
        for j in range(ny):
            for k in range(nz):
                box(V, x0 + i * dx, x1 + i * dx, y0 + j * dy, y1 + j * dy, z0 + k * dz, z1 + k * dz, m)


def _span(c, r):
    return math.floor(c - r), math.ceil(c + r)


def blob(V, cx, cy, cz, rx, ry, rz, m):
    """Stair-stepped ellipsoid. Organic parts only (heads, fruit); hard-surface = box()."""
    if min(rx, ry, rz) <= 0:
        raise ValueError('blob radii must be > 0')
    (x0, x1), (y0, y1), (z0, z1) = _span(cx, rx), _span(cy, ry), _span(cz, rz)
    v = V.view(x0, x1, y0, y1, z0, z1)
    X, Y, Z = np.ogrid[x0:x1 + 1, y0:y1 + 1, z0:z1 + 1]
    v[((X - cx) / rx) ** 2 + ((Y - cy) / ry) ** 2 + ((Z - cz) / rz) ** 2 <= 1] = V.kid(m)


def disc(V, cx, cy, z, r, m):
    (x0, x1), (y0, y1) = _span(cx, r), _span(cy, r)
    v = V.view(x0, x1, y0, y1, z, z)
    X, Y = np.ogrid[x0:x1 + 1, y0:y1 + 1]
    v[:, :, 0][(X - cx) ** 2 + (Y - cy) ** 2 <= r * r] = V.kid(m)


def mirror_x(V):
    """Copy everything on the +x side onto -x (x=0 column is the centre line)."""
    lo, hi = V.bounds()
    if hi[0] < 1:
        return
    V.ensure((-hi[0], lo[1], lo[2]), hi)
    o = V.o
    for x in range(1, hi[0] + 1):
        src = V.a[x - o[0]]
        dst = V.a[-x - o[0]]
        np.copyto(dst, src, where=src != 0)


def rescale(V, f):
    """Resample by factor f (nearest voxel). Returns a new Grid; the caller reassigns V."""
    if f <= 0:
        raise ValueError('scale factor must be > 0')
    lo, hi = V.bounds()
    out = Grid()
    out.keys, out._id = list(V.keys), dict(V._id)
    rng = [np.arange(math.floor(lo[i] * f), math.ceil((hi[i] + 1) * f)) for i in range(3)]
    src = [np.floor((r + .5) / f).astype(int) - V.o[i] for i, r in enumerate(rng)]
    ok = [(s >= 0) & (s < V.a.shape[i]) for i, s in enumerate(src)]
    sub = V.a[np.ix_(*[np.clip(s, 0, V.a.shape[i] - 1) for i, s in enumerate(src)])]
    sub = sub * (ok[0][:, None, None] & ok[1][None, :, None] & ok[2][None, None, :])
    out.o = tuple(int(r[0]) for r in rng)
    out.a = sub.astype(np.uint16)
    return out


def carve(V, region):
    """Remove voxels. region: a Grid (nonzero cells are removed, same lattice coords)."""
    nz = np.argwhere(region.a)
    if not len(nz):
        return
    pts = nz + region.o - V.o
    ok = np.all((pts >= 0) & (pts < V.a.shape), axis=1)
    pts = pts[ok]
    V.a[pts[:, 0], pts[:, 1], pts[:, 2]] = 0


# ---------------------------------------------------------------- meshing

def _runs(mask):
    """Greedy rectangles of equal nonzero id in a 2D (U, V) mask -> list of (u0, u1, v0, v1, id), ends exclusive."""
    U, W = mask.shape
    out = []
    open_ = {}
    m32 = mask.astype(np.int32)
    for v in range(W + 1):
        cur = {}
        if v < W:
            row = m32[:, v]
            ch = np.flatnonzero(np.diff(row, prepend=-1, append=-1))
            for s, e in zip(ch[:-1], ch[1:]):
                i = row[s]
                if i:
                    cur[(int(s), int(e), int(i))] = None
        for k, v0 in open_.items():
            if k not in cur:
                out.append((k[0], k[1], v0, v, k[2]))
        open_ = {k: open_.get(k, v) for k in cur}
    return out


def _quads(V, greedy):
    """Yield (ax, sign, s, u0, u1, v0, v1, id) in grid-local lattice coords; ends exclusive."""
    a = V.a
    pad = np.pad(a, 1)
    solid = pad != 0
    for ax in range(3):
        u, v = (ax + 1) % 3, (ax + 2) % 3
        for sign in (1, -1):
            nb = np.roll(solid, -sign, axis=ax)
            core = tuple(slice(1, -1) for _ in range(3))
            exposed = (solid & ~nb)[core]
            ids = np.where(exposed, a, 0)
            ids = np.moveaxis(ids, (ax, u, v), (0, 1, 2))
            for s in np.flatnonzero(ids.any(axis=(1, 2))):
                sl = ids[s]
                if greedy:
                    for u0, u1, v0, v1, i in _runs(sl):
                        yield ax, sign, int(s), u0, u1, v0, v1, i
                else:
                    for uu, vv in np.argwhere(sl):
                        yield ax, sign, int(s), int(uu), int(uu) + 1, int(vv), int(vv) + 1, int(sl[uu, vv])


# ---------------------------------------------------------------- materials

def _to_srgb(c):
    c = np.clip(c, 0.0, 1.0)
    return np.where(c <= 0.0031308, 12.92 * c, 1.055 * c ** (1 / 2.4) - 0.055)


def _principled(mat):
    # Blender 5.x: nodes are on by default; use_nodes is deprecated, so only touch it if no tree.
    if mat.node_tree is None:
        mat.use_nodes = True
    return next(n for n in mat.node_tree.nodes if n.type == 'BSDF_PRINCIPLED')


def _set_pbr(bsdf, metal):
    bsdf.inputs['Metallic'].default_value = 1.0 if metal else 0.0
    bsdf.inputs['Roughness'].default_value = 0.3 if metal else 0.7


def _flat_material(name, rgb, metal):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    bsdf = _principled(mat)
    c = (*rgb, 1)
    bsdf.inputs['Base Color'].default_value = c
    _set_pbr(bsdf, metal)
    mat.diffuse_color = c
    return mat


def _palette_image(name, keys, colors):
    """1px-per-colour strip. Colours are given linear (like Base Color) and stored sRGB."""
    img = bpy.data.images.get(name)
    if img and tuple(img.size) != (len(keys), 1):
        bpy.data.images.remove(img)
        img = None
    if not img:
        img = bpy.data.images.new(name, len(keys), 1, alpha=False)
    px = np.ones((len(keys), 4), np.float32)
    px[:, :3] = _to_srgb(np.array([colors[k] for k in keys], np.float32))
    img.pixels.foreach_set(px.ravel())
    try:
        img.pack()
    except RuntimeError:
        pass
    return img


def _palette_material(name, img, metal):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    bsdf = _principled(mat)
    nt = mat.node_tree
    tex = nt.nodes.get('Palette') or nt.nodes.new('ShaderNodeTexImage')
    tex.name = 'Palette'
    tex.image = img
    tex.interpolation = 'Closest'
    tex.location = (bsdf.location.x - 350, bsdf.location.y)
    if not bsdf.inputs['Base Color'].is_linked:
        nt.links.new(tex.outputs['Color'], bsdf.inputs['Base Color'])
    _set_pbr(bsdf, metal)
    return mat


# ---------------------------------------------------------------- scene helpers

def _remove_object(ob):
    for child in list(ob.children):
        _remove_object(child)
    me = ob.data
    bpy.data.objects.remove(ob)
    if me and not me.users:
        bpy.data.meshes.remove(me)


def remove_default_cube():
    ob = bpy.data.objects.get('Cube')
    if not ob or ob.type != 'MESH' or len(ob.data.vertices) != 8:
        return False
    _remove_object(ob)
    return True


# ---------------------------------------------------------------- build

_SHADES = (-1.0, -0.35, 0.35, 1.0)


def _apply_grain(V, colors, metallic, grain):
    """Split every key into 4 brightness variants chosen by a hash of the voxel position."""
    a = V.a
    X, Y, Z = np.indices(a.shape, dtype=np.int64)
    X, Y, Z = X + V.o[0], Y + V.o[1], Z + V.o[2]
    h = (((X * 73856093) ^ (Y * 19349663) ^ (Z * 83492791)) >> 3) & 3
    used = sorted(set(int(i) for i in np.unique(a) if i))
    names, cols, metal, remap = [], {}, set(), np.zeros((len(V.keys) + 1, 4), np.uint16)
    for i in used:
        k = V.keys[i - 1]
        for j, sh in enumerate(_SHADES):
            f = 1 + grain * sh
            n = f'{k}~{j}'
            names.append(n)
            cols[n] = tuple(min(max(c * f, 0.0), 1.0) for c in colors[k])
            if k in metallic:
                metal.add(n)
            remap[i, j] = len(names)
    out = np.where(a != 0, remap[a, h], 0).astype(np.uint16)
    return out, names, cols, tuple(metal)


def build(name, V, colors, size=VOXEL_SIZE, metallic=(), mesh='greedy', materials='palette',
          collider=False, replace=True, remove_cube=True, grain=0.08):
    """One mesh object at the origin, centred on x/y, feet on z=0, only exposed faces.

    mesh:      'greedy' (merged rectangles, default) or 'faces' (one quad per voxel face)
    materials: 'palette' (one palette texture) or 'separate' (one flat material per colour key)
    """
    t0 = time.perf_counter()
    if not V.count():
        raise ValueError('V is empty')
    used_keys = [V.keys[i - 1] for i in np.unique(V.a) if i]
    missing = set(used_keys) - set(colors)
    if missing:
        raise KeyError(f'no colour defined for: {sorted(missing)}')
    if mesh not in ('greedy', 'faces'):
        raise ValueError(f"mesh must be 'greedy' or 'faces', not {mesh!r}")
    if materials not in ('palette', 'separate'):
        raise ValueError(f"materials must be 'palette' or 'separate', not {materials!r}")
    warnings = []
    if min(abs(size - VOXEL_SIZE), abs(size - FINE_SIZE)) > 1e-9:
        warnings.append(f'size {size} not {VOXEL_SIZE} or {FINE_SIZE}: rescale shape coords instead')

    # work on a Grid whose ids index `names`/`cols`
    if grain:
        ids, names, cols, metallic = _apply_grain(V, colors, metallic, grain)
    else:
        remap = np.zeros(len(V.keys) + 1, np.uint16)
        names = []
        for i, k in enumerate(V.keys, 1):
            if k in used_keys:
                names.append(k)
                remap[i] = len(names)
        ids, cols = remap[V.a], colors
    W = Grid()
    W.a, W.o = ids, V.o
    t1 = time.perf_counter()

    removed_cube = remove_default_cube() if remove_cube else False
    if replace and (old := bpy.data.objects.get(name)):
        _remove_object(old)

    palette = materials == 'palette'
    if palette:
        img = _palette_image(f'{name}_palette', names, cols)
        mats = [_palette_material(f'{name}_palette', img, False)]
        if any(k in metallic for k in names):
            mats.append(_palette_material(f'{name}_palette_metal', img, True))
        mat_index = np.array([0] + [(1 if k in metallic else 0) for k in names], np.int32)
    else:
        mats = [_flat_material(f'{name}_{k}', cols[k], k in metallic) for k in names]
        mat_index = np.arange(-1, len(names), dtype=np.int32)
        mat_index[0] = 0

    nz = np.argwhere(ids)
    lo, hi = nz.min(0), nz.max(0)
    ox = (lo[0] + hi[0] + 1) / 2
    oy = (lo[1] + hi[1] + 1) / 2
    oz = lo[2]

    q = np.array(list(_quads(W, mesh == 'greedy')), dtype=np.int64)
    t2 = time.perf_counter()
    nq = len(q)

    # corners (nq, 4, 3) in lattice coords; axes cycle (ax, u, v)
    ax, sign, s, u0, u1, v0, v1 = q[:, 0], q[:, 1], q[:, 2], q[:, 3], q[:, 4], q[:, 5], q[:, 6]
    qid = q[:, 7]
    plane = s + (sign > 0)
    uu = np.stack([u0, u1, u1, u0], 1)
    vv = np.stack([v0, v0, v1, v1], 1)
    flip = sign < 0
    uu[flip] = uu[flip][:, ::-1]
    vv[flip] = vv[flip][:, ::-1]
    corners = np.zeros((nq, 4, 3), np.int64)
    for a_ in range(3):
        sel = ax == a_
        corners[sel, :, a_] = plane[sel, None]
        corners[sel, :, (a_ + 1) % 3] = uu[sel]
        corners[sel, :, (a_ + 2) % 3] = vv[sel]
    # the moveaxis in _quads put slice index on axis 0, so these are in grid-local coords
    corners += np.array(W.o)

    flat = corners.reshape(-1, 3)
    mn = flat.min(0)
    span = flat.max(0) - mn + 1
    code = ((flat[:, 0] - mn[0]) * span[1] + (flat[:, 1] - mn[1])) * span[2] + (flat[:, 2] - mn[2])
    uniq, first, inv = np.unique(code, return_index=True, return_inverse=True)
    pts = flat[first].astype(np.float64)
    pts = (pts - np.array([ox, oy, oz])) * size

    me = bpy.data.meshes.new(name)
    me.vertices.add(len(pts))
    me.vertices.foreach_set('co', pts.astype(np.float32).ravel())
    me.loops.add(nq * 4)
    me.loops.foreach_set('vertex_index', inv.astype(np.int32).ravel())
    me.polygons.add(nq)
    me.polygons.foreach_set('loop_start', np.arange(0, nq * 4, 4, dtype=np.int32))
    me.polygons.foreach_set('material_index', mat_index[qid])
    me.polygons.foreach_set('use_smooth', np.zeros(nq, np.bool_))
    if palette:
        uvl = me.uv_layers.new(name='UVMap')
        tu = (qid - 1 + 0.5) / len(names)
        uv = np.empty((nq, 4, 2), np.float32)
        uv[:, :, 0] = tu[:, None]
        uv[:, :, 1] = 0.5
        uvl.data.foreach_set('uv', uv.ravel())
    me.update(calc_edges=True)
    me.validate()
    for mat in mats:
        me.materials.append(mat)
    ob = bpy.data.objects.new(name, me)
    coll = bpy.context.collection
    coll.objects.link(ob)

    col_name = None
    if collider:
        w_lo = (np.array(lo) + W.o - np.array([ox, oy, oz])) * size
        w_hi = (np.array(hi) + 1 + W.o - np.array([ox, oy, oz])) * size
        cx = [(a_ + b_) / 2 for a_, b_ in zip(w_lo, w_hi)]
        cs = [b_ - a_ for a_, b_ in zip(w_lo, w_hi)]
        cverts = [(cx[0] + dx * cs[0] / 2, cx[1] + dy * cs[1] / 2, cx[2] + dz * cs[2] / 2)
                  for dx in (-1, 1) for dy in (-1, 1) for dz in (-1, 1)]
        cfaces = [(0, 1, 3, 2), (4, 6, 7, 5), (0, 4, 5, 1), (2, 3, 7, 6), (0, 2, 6, 4), (1, 5, 7, 3)]
        cme = bpy.data.meshes.new(f'{name}-convcolonly')
        cme.from_pydata(cverts, [], cfaces)
        col = bpy.data.objects.new(f'{name}-convcolonly', cme)
        col.parent = ob
        col.display_type = 'WIRE'
        col.hide_render = True
        coll.objects.link(col)
        col_name = col.name

    if nq > MAX_FACES:
        warnings.append(f'{nq} faces > {MAX_FACES}: merge noisy colours or drop sub-visible detail')
    t3 = time.perf_counter()
    h = int(hi[2] - lo[2] + 1)
    return {'object': ob.name, 'voxels': int(np.count_nonzero(ids)), 'faces': len(me.polygons),
            'verts': len(me.vertices), 'materials': len(mats), 'height_voxels': h, 'size': size,
            'height_m': round(h * size, 2), 'warnings': warnings, 'collider': col_name,
            'removed_default_cube': removed_cube,
            'ms': {'prep': round((t1 - t0) * 1e3, 1), 'mesh_quads': round((t2 - t1) * 1e3, 1),
                   'write': round((t3 - t2) * 1e3, 1), 'total': round((t3 - t0) * 1e3, 1)}}


# ---------------------------------------------------------------- export

def export_glb(obj, filepath):
    """Export one built object (plus its collider child) as a .glb for Godot."""
    ob = bpy.data.objects[obj] if isinstance(obj, str) else obj
    path = bpy.path.abspath(filepath)
    if not path.lower().endswith('.glb'):
        path += '.glb'
    for o in bpy.context.view_layer.objects:
        o.select_set(False)
    for o in [ob, *ob.children_recursive]:
        o.hide_set(False)
        o.select_set(True)
    bpy.context.view_layer.objects.active = ob
    bpy.ops.export_scene.gltf(filepath=path, export_format='GLB', use_selection=True,
                              export_apply=True, export_yup=True)
    return path


# ---------------------------------------------------------------- states

def build_states(name, model, states, **kw):
    """Build one Element's states from one shape function.
    model(state) -> (V, colors) for state name e.g. 'On'; geometry or colour may differ per state.
    Builds objects `<name>_<state>`; returns {state: build() result}. Pass size=, grain=, collider= via kw."""
    return {s: build(f'{name}_{s}', *model(s), **kw) for s in states}


